window.products.push({"id":206246,"name":"McCulloch A275-002 Short Nylon Brush (5 Pack)","category":"homeandappliances","retail price":6.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/61juyl3MuaL._AC_SL1302_.jpg","description":"This five pack of short nylon utility brushes is designed for scrubbing especially tough stains. Ideal for use on many surfaces around the home, including carpet, ceramic tile, grouting and more. It is always recommended to spot test any surface in an inconspicuous area prior to scrubbing to ensure scratching does not occur. This short nylon utility brush, part number A275-002-5, works with model MC1275.","images":["https://m.media-amazon.com/images/I/61juyl3MuaL._AC_SL1302_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"McCulloch","source_asin":"B07CSMBDK5","category_path":"Home & Kitchen"},"sku":"BM-206246","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07CSMBDK5","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07CSMBDK5","price_pending":true,"merchant_ready":false});
